/* Farbod offline graph renderer: small vis-compatible subset used by diagram.html. */
(function(g){
  class DataSet{
    constructor(items){this.map=new Map(); (items||[]).forEach(x=>this.add(x));}
    add(items){(Array.isArray(items)?items:[items]).forEach(x=>{if(x&&x.id!=null)this.map.set(String(x.id),Object.assign({},x));});}
    get(id){if(id==null)return Array.from(this.map.values()); return this.map.get(String(id));}
    update(items){this.add(items);}
    remove(id){(Array.isArray(id)?id:[id]).forEach(x=>this.map.delete(String(x)));}
    forEach(fn){this.map.forEach(fn);}
  }
  class Network{
    constructor(container,data,options){
      this.container=container; this.nodes=data.nodes; this.edges=data.edges; this.options=options||{}; this.handlers={}; this.positions={};
      this._render();
    }
    on(name,fn){(this.handlers[name]||(this.handlers[name]=[])).push(fn);}
    _emit(name,p){(this.handlers[name]||[]).forEach(fn=>fn(p||{}));}
    getPositions(ids){const out={}; (ids||[]).forEach(id=>{if(this.positions[id])out[id]=this.positions[id];}); return out;}
    _render(){
      const c=this.container; c.innerHTML='';
      const w=c.clientWidth||900,h=c.clientHeight||500;
      const ns=this.nodes.get(), es=this.edges.get();
      const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'); svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.style.display='block';
      const layerE=document.createElementNS(svg.namespaceURI,'g'), layerN=document.createElementNS(svg.namespaceURI,'g');svg.append(layerE,layerN);c.appendChild(svg);
      const positions={}; const cols=Math.max(1,Math.ceil(Math.sqrt(ns.length||1))); const gapX=w/(cols+1), gapY=h/(Math.ceil((ns.length||1)/cols)+1);
      ns.forEach((n,i)=>{let x=n.x!=null?Number(n.x):((i%cols)+1)*gapX;let y=n.y!=null?Number(n.y):((Math.floor(i/cols))+1)*gapY; if(Math.abs(x)<5)x=w/2; if(Math.abs(y)<5)y=h/2; positions[n.id]={x,y}; this.positions[n.id]={x,y};});
      const edgeEls=[];
      es.forEach(e=>{const line=document.createElementNS(svg.namespaceURI,'line');line.setAttribute('stroke','currentColor');line.setAttribute('stroke-opacity','.45');line.setAttribute('stroke-width','2');line.style.cursor='pointer';layerE.appendChild(line); edgeEls.push([e,line]);line.addEventListener('click',()=>this._emit('selectEdge',{edges:[e.id]}));});
      ns.forEach(n=>{
        const gEl=document.createElementNS(svg.namespaceURI,'g');gEl.style.cursor='grab';
        const text=document.createElementNS(svg.namespaceURI,'text');text.textContent=n.label||'';text.setAttribute('text-anchor','middle');text.setAttribute('dominant-baseline','middle');text.setAttribute('font-size','13');text.setAttribute('font-family','Vazirmatn, Tahoma, sans-serif');
        const rect=document.createElementNS(svg.namespaceURI,'rect'); const width=Math.max(110,Math.min(240,(n.label||'').length*8+30)),height=42;rect.setAttribute('x',-width/2);rect.setAttribute('y',-height/2);rect.setAttribute('width',width);rect.setAttribute('height',height);rect.setAttribute('rx','12');rect.setAttribute('fill','rgba(255,255,255,.82)');rect.setAttribute('stroke','#0b8f67');rect.setAttribute('stroke-width','1.5');gEl.append(rect,text);layerN.appendChild(gEl);
        let dragging=false,start={x:0,y:0},base={x:positions[n.id].x,y:positions[n.id].y};
        const move=(ev)=>{if(!dragging)return;const r=svg.getBoundingClientRect();positions[n.id].x=Math.max(10,Math.min(w-10,ev.clientX-r.left-start.x+base.x));positions[n.id].y=Math.max(10,Math.min(h-10,ev.clientY-r.top-start.y+base.y));this.positions[n.id]=positions[n.id];draw();};
        const up=()=>{if(!dragging)return;dragging=false;gEl.style.cursor='grab';this._emit('dragEnd',{nodes:[n.id]});window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);};
        gEl.addEventListener('mousedown',ev=>{dragging=true;base={...positions[n.id]};start={x:ev.clientX-svg.getBoundingClientRect().left,y:ev.clientY-svg.getBoundingClientRect().top};gEl.style.cursor='grabbing';window.addEventListener('mousemove',move);window.addEventListener('mouseup',up);});
        function draw(){gEl.setAttribute('transform',`translate(${positions[n.id].x},${positions[n.id].y})`);edgeEls.forEach(([e,l])=>{const a=positions[e.from],b=positions[e.to];if(a&&b){l.setAttribute('x1',a.x);l.setAttribute('y1',a.y);l.setAttribute('x2',b.x);l.setAttribute('y2',b.y);}})}
        draw();
      });
      this._svg=svg;
    }
  }
  g.vis=g.vis||{};g.vis.DataSet=DataSet;g.vis.Network=Network;
})(window);
